CREATE TABLE review_plan (id INTEGER PRIMARY KEY CHECK(id=1), data TEXT NOT NULL CHECK(json_valid(data) AND length(CAST(data AS BLOB)) <= 65536), digest TEXT NOT NULL) STRICT;
CREATE TABLE review_operations (id TEXT PRIMARY KEY, request TEXT NOT NULL CHECK(json_valid(request) AND length(CAST(request AS BLOB)) <= 4096), request_hash TEXT NOT NULL, recorded_at_ms INTEGER NOT NULL, result TEXT NOT NULL CHECK(json_valid(result) AND length(CAST(result AS BLOB)) <= 65536), digest TEXT NOT NULL) STRICT;
CREATE TABLE recall_review_events (id TEXT PRIMARY KEY, attempt_id TEXT NOT NULL UNIQUE REFERENCES study_attempts(id), activity_revision_id TEXT NOT NULL REFERENCES lesson_activity_revisions(id), prior_event_id TEXT UNIQUE REFERENCES recall_review_events(id), reviewed_at_ms INTEGER NOT NULL, study_day INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data) AND length(CAST(data AS BLOB)) <= 8192), digest TEXT NOT NULL) STRICT;
CREATE INDEX recall_review_time ON recall_review_events(reviewed_at_ms);
CREATE TABLE recall_states (activity_revision_id TEXT PRIMARY KEY REFERENCES lesson_activity_revisions(id), event_id TEXT NOT NULL UNIQUE REFERENCES recall_review_events(id)) STRICT;
CREATE TABLE review_journal (position INTEGER PRIMARY KEY CHECK(position>0 AND position<=9007199254740991), kind TEXT NOT NULL CHECK(kind IN ('plan','event')), record_id TEXT NOT NULL, UNIQUE(kind,record_id)) STRICT;
CREATE TABLE assessment_runs (id TEXT PRIMARY KEY, operation_id TEXT NOT NULL UNIQUE, request TEXT NOT NULL CHECK(json_valid(request) AND length(CAST(request AS BLOB))<=4096), request_hash TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data) AND length(CAST(data AS BLOB))<=262144), digest TEXT NOT NULL) STRICT;
CREATE TABLE assessment_parts (session_id TEXT PRIMARY KEY, assessment_id TEXT NOT NULL REFERENCES assessment_runs(id), part_index INTEGER NOT NULL CHECK(part_index>=0), unit_id TEXT NOT NULL REFERENCES units(id), composition_id TEXT NOT NULL REFERENCES lesson_revisions(id), UNIQUE(assessment_id,part_index)) STRICT;
